using System;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Interop;using System.Windows.Media;using System.Windows.Threading;using Lumina;
class IntegrationTests {
static void Pump(){var f=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.Background,new Action(()=>f.Continue=false));Dispatcher.PushFrame(f);}
static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
[STAThread]static int Main(){try{var app=new Application();app.ShutdownMode=ShutdownMode.OnExplicitShutdown;var windows=new List<Window>();var items=new List<RunningWindow>();for(int i=0;i<6;i++){var w=new Window{Title="Integration "+i,Width=300,Height=200,Content=new TextBlock{Text="Live "+i}};w.Show();windows.Add(w);items.Add(new RunningWindow{Handle=new WindowInteropHelper(w).Handle,ProcessId=(uint)System.Diagnostics.Process.GetCurrentProcess().Id,Title=w.Title});}Pump();var area=SystemParameters.WorkArea;var pop=new ThumbnailPopup(items,new Point(area.Width/2,area.Bottom-60),VisualTreeHelper.GetDpi(windows[0]).DpiScaleX);Pump();var flags=BindingFlags.NonPublic|BindingFlags.Instance;var cards=(IList)typeof(ThumbnailPopup).GetField("cards",flags).GetValue(pop);Check(cards.Count==5,"preview limited to five windows");foreach(var c in cards)Check((IntPtr)c.GetType().GetField("Thumb").GetValue(c)!=IntPtr.Zero,"native live thumbnail registered");var first=cards[0];var root=(Border)first.GetType().GetField("Root").GetValue(first);var content=(Grid)root.Child;var close=content.Children.OfType<Button>().Single();close.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Pump();Check(!windows[0].IsVisible&&windows[1].IsVisible,"close targets only selected window");var snap=typeof(ThumbnailPopup).GetMethod("SnapTarget",BindingFlags.NonPublic|BindingFlags.Static);var screen=System.Windows.Forms.Screen.PrimaryScreen;Check((bool)snap.Invoke(null,new object[]{items[1],screen.Bounds.Left,screen.Bounds.Top+100}),"left snap accepted");Pump();Check(Math.Abs(windows[1].Width*VisualTreeHelper.GetDpi(windows[1]).DpiScaleX-screen.WorkingArea.Width/2)<20,"left snap half-screen width");Check((bool)snap.Invoke(null,new object[]{items[1],screen.Bounds.Right-1,screen.Bounds.Top+100}),"right snap accepted");Pump();Check((bool)snap.Invoke(null,new object[]{items[1],screen.Bounds.Left+100,screen.Bounds.Top}),"top snap accepted");Pump();Check(windows[1].WindowState==WindowState.Maximized,"top snap maximizes");pop.Dispose();foreach(var w in windows)w.Close();
var controller=(Controller)Activator.CreateInstance(typeof(Controller),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{false},null);var title=new StackPanel();var tabs=new TabControl();var page=new TabItem{Header="Appearance",Content=new StackPanel()};((StackPanel)page.Content).Children.Add(new TextBlock{Text="透明度"});tabs.Items.Add(new TabItem{Header="Other"});tabs.Items.Add(page);typeof(Controller).GetMethod("InstallSettingsSearch",flags).Invoke(controller,new object[]{title,tabs});var input=title.Children.OfType<TextBox>().Single();input.Text="透明";var results=(StackPanel)title.Children.OfType<ScrollViewer>().Single().Content;Check(results.Children.Count==1&&results.Children[0] is Button,"setting search returns matching option");((Button)results.Children[0]).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(tabs.SelectedItem==page&&input.Text=="","search result navigates to page");controller.ShuttingDown=true;controller.Board.Close();controller.Dock.Close();
MenuAppearanceChecks.Run();Check(true,"menu appearance regression");FeedbackChecks.Run();Check(true,"feedback regression");Feedback18Checks.Run();Check(true,"feedback 1.8 regression");Console.WriteLine("ALL PASS");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
